#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include "kernel.h"
#include <string>

static void check_fp32_contiguous_cuda(
    const torch::Tensor& tensor, const std::string& name) {
    TORCH_CHECK(tensor.is_cuda(), name, " must be a CUDA tensor");
    TORCH_CHECK(
        tensor.dtype() == torch::kFloat32,
        name, " must have float32 dtype, got ", tensor.dtype());
    TORCH_CHECK(tensor.is_contiguous(), name, " must be contiguous");
}

// Destination-passing-style entry for the AdaLayerNormZero modulation
// extraction Linear-with-bias + 6-chunk multi-output kernel. Per
// definition.json:
//   emb        : [batch_size, inner_dim=3072] fp32
//   weight     : [output_dim=18432, inner_dim=3072] fp32
//   bias       : [output_dim=18432] fp32
//   shift_msa  : [batch_size, inner_dim=3072] fp32 (DPS)
//   scale_msa  : [batch_size, inner_dim=3072] fp32 (DPS)
//   gate_msa   : [batch_size, inner_dim=3072] fp32 (DPS)
//   shift_mlp  : [batch_size, inner_dim=3072] fp32 (DPS)
//   scale_mlp  : [batch_size, inner_dim=3072] fp32 (DPS)
//   gate_mlp   : [batch_size, inner_dim=3072] fp32 (DPS)
//
// inner_dim = 3072 and output_dim = inner_dim * 6 = 18432 are pinned
// by the problem definition. Const-axis pins are enforced on EVERY
// tensor that the kernel indexes with that fixed assumption,
// following the runtime-check audit discipline.

void run(
    torch::Tensor emb,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor shift_msa,
    torch::Tensor scale_msa,
    torch::Tensor gate_msa,
    torch::Tensor shift_mlp,
    torch::Tensor scale_mlp,
    torch::Tensor gate_mlp
) {
    constexpr int64_t kInnerDim = 3072;
    constexpr int64_t kOutputDim = 6 * kInnerDim;  // 18432

    check_fp32_contiguous_cuda(emb, "emb");
    check_fp32_contiguous_cuda(weight, "weight");
    check_fp32_contiguous_cuda(bias, "bias");
    check_fp32_contiguous_cuda(shift_msa, "shift_msa");
    check_fp32_contiguous_cuda(scale_msa, "scale_msa");
    check_fp32_contiguous_cuda(gate_msa, "gate_msa");
    check_fp32_contiguous_cuda(shift_mlp, "shift_mlp");
    check_fp32_contiguous_cuda(scale_mlp, "scale_mlp");
    check_fp32_contiguous_cuda(gate_mlp, "gate_mlp");

    TORCH_CHECK(emb.dim() == 2, "emb must be 2D [B, inner_dim]");
    TORCH_CHECK(weight.dim() == 2, "weight must be 2D [output_dim, inner_dim]");
    TORCH_CHECK(bias.dim() == 1, "bias must be 1D [output_dim]");
    TORCH_CHECK(shift_msa.dim() == 2, "shift_msa must be 2D");
    TORCH_CHECK(scale_msa.dim() == 2, "scale_msa must be 2D");
    TORCH_CHECK(gate_msa.dim() == 2, "gate_msa must be 2D");
    TORCH_CHECK(shift_mlp.dim() == 2, "shift_mlp must be 2D");
    TORCH_CHECK(scale_mlp.dim() == 2, "scale_mlp must be 2D");
    TORCH_CHECK(gate_mlp.dim() == 2, "gate_mlp must be 2D");

    const int64_t batch_size = emb.size(0);

    TORCH_CHECK(emb.size(1) == kInnerDim,
                "emb.size(1) must equal inner_dim=3072, got ", emb.size(1));
    TORCH_CHECK(weight.size(0) == kOutputDim,
                "weight.size(0) must equal output_dim=18432, got ",
                weight.size(0));
    TORCH_CHECK(weight.size(1) == kInnerDim,
                "weight.size(1) must equal inner_dim=3072, got ",
                weight.size(1));
    TORCH_CHECK(bias.size(0) == kOutputDim,
                "bias.size(0) must equal output_dim=18432, got ",
                bias.size(0));

    auto check_output = [&](const torch::Tensor& t, const std::string& name) {
        TORCH_CHECK(t.size(0) == batch_size,
                    name, ".size(0) must equal emb.size(0) (= batch_size)");
        TORCH_CHECK(t.size(1) == kInnerDim,
                    name, ".size(1) must equal inner_dim=3072, got ",
                    t.size(1));
    };
    check_output(shift_msa, "shift_msa");
    check_output(scale_msa, "scale_msa");
    check_output(gate_msa, "gate_msa");
    check_output(shift_mlp, "shift_mlp");
    check_output(scale_mlp, "scale_mlp");
    check_output(gate_mlp, "gate_mlp");

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    problem_035_flux_ada_layer_norm_zero_modulation_extraction_launcher(
        emb, weight, bias,
        shift_msa, scale_msa, gate_msa,
        shift_mlp, scale_mlp, gate_mlp,
        stream);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def(
        "run", &run,
        "AdaLayerNormZero modulation extraction: fp32 Linear-with-bias "
        "(K=inner_dim=3072, N=output_dim=18432) + 6-chunk multi-output "
        "DPS in one custom CUDA kernel. inner_dim=3072 pinned on every "
        "input/output tensor.");
}

#include "kernel.h"
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>

// AdaLayerNormZero modulation extraction: one fused fp32
// Linear-with-bias + 6-chunk multi-output DPS kernel.
//
// Per-element math (matching the reference
//   `emb_out = emb @ weight.T + bias; chunk(6, dim=1)`):
//
//   modulation[b, n] = sum_{k=0}^{K-1} weight[n, k] * emb[b, k]
//                    + bias[n]
//   for n in [0, N=6*H) where H = inner_dim = 3072.
//
// Then chunk along n:
//   chunk_idx = n / H ;  local_n = n % H
//   outputs[chunk_idx][b, local_n] = modulation[b, n]
//
// Output layout per the canonical reference:
//   chunk 0 = shift_msa, chunk 1 = scale_msa, chunk 2 = gate_msa,
//   chunk 3 = shift_mlp, chunk 4 = scale_mlp, chunk 5 = gate_mlp.
//
// Kernel topology:
//   * Grid (B, N_tiles) where N_tiles = N / kWarpsPerCta = 18432 / 8
//     = 2304. Each CTA owns one (b, n_tile) and computes the
//     `kWarpsPerCta = 8` output elements in that tile via 8 warps.
//   * BLOCK_THREADS = 256 (8 warps of 32 lanes).
//   * Each CTA caches emb[b, :K=3072] in shared memory once
//     (12 KiB fp32) so the 8 warps reuse it across their 8 K-
//     reductions instead of fetching from L2/HBM per warp.
//   * Per output element: 32 lanes stride-load
//     `weight[n, k0..K-1]` from global, multiply by the shared
//     `emb[b, k]`, accumulate a per-lane fp32 partial sum, warp-
//     shuffle reduce across the 32 lanes, lane 0 writes
//     `partial + bias[n]` to the correct chunked output.
//
// Pinning: H=3072 and N=18432=6*H are pinned by the problem
// definition. The kernel uses `constexpr int kH = 3072` etc. and
// the host launcher checks every tensor's pinned dims via TORCH_CHECK
// to enforce the runtime-check audit discipline.

namespace {

constexpr int kH = 3072;
constexpr int kN = 18432;          // = 6 * kH
constexpr int kNumOutputs = 6;
constexpr int kBlockThreads = 256;
constexpr int kWarpSize = 32;
constexpr int kWarpsPerCta = kBlockThreads / kWarpSize;  // 8
constexpr int kNTilesPerCta = kWarpsPerCta;              // 8 output n's per CTA

static_assert(kN % kWarpsPerCta == 0,
              "kN must be divisible by kWarpsPerCta");

__device__ __forceinline__ float warp_reduce_sum(float v) {
    #pragma unroll
    for (int off = kWarpSize / 2; off > 0; off >>= 1) {
        v += __shfl_xor_sync(0xffffffff, v, off);
    }
    return v;
}

__global__ void __launch_bounds__(kBlockThreads, 4) k_ada_modulation_extract(
    const float* __restrict__ emb,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ shift_msa,
    float* __restrict__ scale_msa,
    float* __restrict__ gate_msa,
    float* __restrict__ shift_mlp,
    float* __restrict__ scale_mlp,
    float* __restrict__ gate_mlp
) {
    const int b = blockIdx.x;
    const int n_tile_base = blockIdx.y * kWarpsPerCta;
    const int tid = threadIdx.x;
    const int warp_id = tid / kWarpSize;
    const int lane = tid & (kWarpSize - 1);

    __shared__ float s_emb[kH];
    #pragma unroll 4
    for (int k = tid; k < kH; k += kBlockThreads) {
        s_emb[k] = emb[b * kH + k];
    }
    __syncthreads();

    const int n = n_tile_base + warp_id;

    float partial = 0.0f;
    const float* w_row = weight + (size_t)n * kH;
    for (int k = lane; k < kH; k += kWarpSize) {
        partial += w_row[k] * s_emb[k];
    }
    partial = warp_reduce_sum(partial);

    if (lane == 0) {
        const float out_val = partial + bias[n];
        const int chunk_idx = n / kH;
        const int local_n = n - chunk_idx * kH;

        float* out_ptrs[kNumOutputs] = {
            shift_msa, scale_msa, gate_msa,
            shift_mlp, scale_mlp, gate_mlp
        };
        out_ptrs[chunk_idx][b * kH + local_n] = out_val;
    }
}

}  // namespace

void problem_035_flux_ada_layer_norm_zero_modulation_extraction_launcher(
    const torch::Tensor& emb,
    const torch::Tensor& weight,
    const torch::Tensor& bias,
    torch::Tensor& shift_msa,
    torch::Tensor& scale_msa,
    torch::Tensor& gate_msa,
    torch::Tensor& shift_mlp,
    torch::Tensor& scale_mlp,
    torch::Tensor& gate_mlp,
    cudaStream_t stream
) {
    const int batch_size = static_cast<int>(emb.size(0));

    dim3 grid(batch_size, kN / kWarpsPerCta);
    dim3 block(kBlockThreads);

    k_ada_modulation_extract<<<grid, block, 0, stream>>>(
        emb.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        shift_msa.data_ptr<float>(),
        scale_msa.data_ptr<float>(),
        gate_msa.data_ptr<float>(),
        shift_mlp.data_ptr<float>(),
        scale_mlp.data_ptr<float>(),
        gate_mlp.data_ptr<float>()
    );

    TORCH_CHECK(cudaGetLastError() == cudaSuccess,
                "problem_035 ada modulation extract kernel launch failed");
}

#pragma once

#include <torch/extension.h>
#include <cuda_runtime.h>

// Host launcher for the AdaLayerNormZero modulation-extraction
// Linear-with-bias + 6-chunk multi-output DPS kernel:
//
//   modulation[b, n] = sum_k weight[n, k] * emb[b, k] + bias[n]
//   for n in [0, 6*inner_dim).
//   Then chunk along n into six [B, inner_dim] outputs.
//
// emb            : [B, inner_dim=3072] fp32 row-major.
// weight         : [output_dim=18432, inner_dim=3072] fp32 row-major.
// bias           : [output_dim=18432] fp32.
// outputs (DPS, pre-allocated):
//   shift_msa    : [B, inner_dim=3072] fp32 row-major.
//   scale_msa    : [B, inner_dim=3072] fp32 row-major.
//   gate_msa     : [B, inner_dim=3072] fp32 row-major.
//   shift_mlp    : [B, inner_dim=3072] fp32 row-major.
//   scale_mlp    : [B, inner_dim=3072] fp32 row-major.
//   gate_mlp     : [B, inner_dim=3072] fp32 row-major.
//
// inner_dim = 3072 and output_dim = 6 * inner_dim = 18432 are pinned
// by the problem definition. B = batch_size varies per workload.
void problem_035_flux_ada_layer_norm_zero_modulation_extraction_launcher(
    const torch::Tensor& emb,
    const torch::Tensor& weight,
    const torch::Tensor& bias,
    torch::Tensor& shift_msa,
    torch::Tensor& scale_msa,
    torch::Tensor& gate_msa,
    torch::Tensor& shift_mlp,
    torch::Tensor& scale_mlp,
    torch::Tensor& gate_mlp,
    cudaStream_t stream);
